        B_c = B.contiguous()
        M, K = A_c.shape
        C = torch.empty((M, 1), device=A.device, dtype=torch.float32)
        # Global work-stealing row counter, zero-initialized on the same
        # stream the kernel will be launched on so ordering is preserved.
        row_counter = torch.zeros(1, dtype=torch.int32, device=A.device)
        module = self._module if self._module is not None else _get_module()
        self._module = module
        stream = torch.cuda.current_stream()
