            block,
            [
                u64(A_c.data_ptr()),
                u64(B_c.data_ptr()),
                u64(C.data_ptr()),
                i64(M),
                i64(K),
                u64(row_counter.data_ptr()),
            ],
            stream=stream,
        )
        return C

