    one or more output rows. Rows are assigned to blocks dynamically via
    a global atomic work-stealing counter (rather than a fixed
    ctaid.x/nctaid.x grid-stride), which balances work evenly across all
    resident blocks/SMs regardless of whether M divides evenly by the
    launched grid size, eliminating the per-SM active-cycle imbalance
    observed with the previous static striding scheme.
    """
    def __init__(self):
        super().__init__()
        self._module = None
        self._threads = 256
        # Empirically-derived occupancy limit for this kernel: with 256
        # threads/block, the SM89 (Ada Lovelace) hardware limit of 1536
        # resident threads/SM caps occupancy at floor(1536 / 256) = 6
        # blocks/SM by thread count. However, profiling shows this kernel
        # actually uses 48 registers/thread (12288 registers/block), and
        # the SM89 register-file limit of 65536 registers/SM caps
        # occupancy at floor(65536 / 12288) = 5 blocks/SM -- the register
        # limit, not the thread-count limit, is the true binding
        # constraint. Using 5 blocks/SM sizes the persistent-CTA grid to
        # roughly one full occupancy wave. Because row assignment is now
        # dynamic (atomic work-stealing), exact divisibility of M by the
        # grid size is no longer required for good load balance.
        self._blocks_per_sm = 5
    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.dtype == torch.float32 and B.dtype == torch.float32, \
            "Expect float32 tensors"
        assert A.dim() == 2, "A must be 2D (M, K)"
        assert B.dim() == 2 and B.size(1) == 1, "B must be (K, 1)"
        assert A.size(1) == B.size(0), "Inner dimensions must match"
        A_c = A.contiguous()
        B_c = B.contiguous()
        M, K = A_c.shape
        C = torch.empty((M, 1), device=A.device, dtype=torch.float32)
        # Global work-stealing row counter, zero-initialized on the same
        # stream the kernel will be launched on so ordering is preserved.
